helpers.stopNeed:
(name, fn, kind) => {
  let r = null, err = null;
  try { r = fn(); } catch (e) { err = e; }
  const hasKind = !!r && r.checks.some((c) => c.level === "need" && c.kind === kind);
  const noNaN = !!r && r.pieces.every((p) => ![p.w, p.h, p.kg].some(Number.isNaN));
  const ok = !err && hasKind && noNaN;
  if (!ok) ng++;
  console.log((ok ? "OK " : "NG ") + name + (err ? "  例外 " + err.message : !hasKind ? "  " + kind + " が出ていない" : !noNaN ? "  片に NaN" : ""));
}

